/**
 * Browser e2e for the web app (headless Chromium): proofs are generated by bb.js WASM in the
 * page's Web Worker — nothing is mocked. Expects relayer (:8080, FAUCET=1), indexer (:8081) and
 * the web app (:4001) to be running against the local network. Screenshots → .run/screens/.
 *
 *   npx tsx src/web.ts            (WEB_URL to override)
 */
import { mkdirSync } from "node:fs";
import { join } from "node:path";
import { chromium, type Page } from "playwright";
import { ROOT, log } from "./env.js";

const WEB = process.env.WEB_URL ?? "http://localhost:4001";
const SHOTS = join(ROOT, ".run", "screens");

async function shot(p: Page, name: string) {
  await p.screenshot({ path: join(SHOTS, `${name}.png`), fullPage: true });
}

/** Pages are server-rendered while locked; wait until the session is unlocked (and hydrated) before typing. */
async function ready(p: Page) {
  await p.getByTitle(/click to lock/).waitFor({ timeout: 30_000 });
  await p.getByText(/^Locked ·/).waitFor({ state: "detached", timeout: 30_000 });
}

async function unlock(p: Page) {
  await p.goto(WEB + "/");
  await p.getByRole("button", { name: "Unlock", exact: true }).click();
  await p.getByRole("dialog").getByRole("button", { name: /demo account/i }).click();
  await p.getByRole("heading", { name: "Wallet", level: 1 }).waitFor({ timeout: 30_000 });
}

async function balanceText(p: Page): Promise<string> {
  await p.goto(WEB + "/");
  await ready(p);
  await p.getByRole("button", { name: "Show" }).click();
  return (await p.locator("section[aria-labelledby=bal-h] div").filter({ hasText: "USDC" }).first().innerText()).trim();
}

async function waitBalance(p: Page, expect: string, timeoutMs = 120_000) {
  const t0 = Date.now();
  for (;;) {
    const b = await balanceText(p);
    if (b.includes(expect)) return b;
    if (Date.now() - t0 > timeoutMs) throw new Error(`balance never reached ${expect} (last: ${b})`);
    await p.waitForTimeout(3_000);
  }
}

async function main() {
  mkdirSync(SHOTS, { recursive: true });
  const browser = await chromium.launch({ channel: "chromium" });
  const ctxA = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const ctxB = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const alice = await ctxA.newPage();
  const bob = await ctxB.newPage();
  const errors: string[] = [];
  for (const p of [alice, bob]) p.on("pageerror", (e) => errors.push(e.message));
  if (process.env.WEB_DEBUG) alice.on("console", (m) => console.log("   [console]", m.text().slice(0, 300)));
  alice.on("worker", (w) => w.on("console", (m) => process.env.WEB_DEBUG && console.log("   [worker]", m.text().slice(0, 300))));

  log("unlock two demo accounts");
  await unlock(alice);
  await unlock(bob);
  await shot(alice, "1-wallet-empty");
  log(`   alice crossOriginIsolated=${await alice.evaluate(() => crossOriginIsolated)}`);

  log("bob's shielded address from the Receive screen");
  await bob.goto(WEB + "/receive");
  await ready(bob);
  await bob.getByRole("heading", { name: "Receive", level: 1 }).waitFor();
  const bobAddr = (await bob.locator("section[aria-labelledby=addr-h] code").innerText()).trim();
  if (!bobAddr.startsWith("zk1")) throw new Error("no zk1 address");
  await shot(bob, "4-receive");

  log("alice deposits 2,350 via a one-time address + testnet faucet");
  await alice.goto(WEB + "/deposit");
  await ready(alice);
  await alice.getByRole("heading", { name: "Deposit", level: 1 }).waitFor();
  await shot(alice, "2-deposit");
  await alice.getByRole("button", { name: "Deposit 2,350 USDC" }).click();
  await alice.getByRole("button", { name: /Testnet faucet/ }).click({ timeout: 30_000 });
  await alice.getByText(/Relayer moved it into the pool/).first().waitFor({ timeout: 90_000 });
  log("   " + (await waitBalance(alice, "2,344.125")).replace(/\s+/g, " "));
  await shot(alice, "1-wallet-funded");

  log("alice sends 250 to bob (proof generated in the browser)");
  await alice.goto(WEB + "/send");
  await ready(alice);
  await alice.locator("#to").fill(bobAddr);
  await alice.locator("#amt").fill("250");
  await alice.getByRole("button", { name: "Generate proof and send" }).click();
  await alice
    .getByRole("button", { name: "Sent · send another" })
    .waitFor({ timeout: 180_000 })
    .catch(async (e) => {
      await shot(alice, "fail-send");
      const alert = await alice.getByRole("alert").allInnerTexts().catch(() => []);
      throw new Error(`send did not complete: ${alert.join(" | ") || e.message}`);
    });
  const inspector = await alice.locator("section[aria-labelledby=pi-h]").innerText();
  log("   inspector: " + inspector.split("\n").slice(2, 10).join(" | "));
  await alice.getByRole("button", { name: "Verify locally" }).click();
  await alice.getByText(/^Valid: the proof verifies/).waitFor({ timeout: 120_000 });
  await alice.getByRole("button", { name: /Show \d+ public inputs/ }).click();
  await shot(alice, "3-send-done");

  log("bob finds the note");
  log("   " + (await waitBalance(bob, "250.00")).replace(/\s+/g, " "));
  await bob.goto(WEB + "/receive");
  await ready(bob);
  await bob.getByText(/\+250\.00 USDC/).waitFor({ timeout: 30_000 });
  await shot(bob, "4-receive-incoming");

  log("alice withdraws 1,000 (Fast)");
  await alice.goto(WEB + "/withdraw");
  await ready(alice);
  await alice.locator("#w-amt").fill("1,000");
  await alice.getByRole("button", { name: /^Fast/ }).click();
  await shot(alice, "5-withdraw");
  await alice.getByRole("button", { name: "Schedule 1 piece" }).click();
  await alice.getByText(/piece scheduled/).waitFor({ timeout: 240_000 });
  await shot(alice, "5-withdraw-scheduled");

  log("verify page");
  await alice.goto(WEB + "/verify");
  await alice.getByText("Notes in the pool").waitFor();
  await alice.waitForTimeout(2_000);
  await shot(alice, "6-verify");

  await browser.close();
  if (errors.length) {
    console.error("page errors:", errors);
    process.exit(1);
  }
  log(`WEB E2E PASSED — screenshots in ${SHOTS}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
